    fs.mkdirSync(path.dirname(outFile), { recursive: true });
    fs.writeFileSync(outFile, renderPage(page, pages));
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages));

  return { pages, outputDir };
}

